// 1. Obter texto do CSV retornado pelo nó HTTP anterior
let csvText = '';
if (typeof $input.first().json.data === 'string') {
  csvText = $input.first().json.data;
} else if (typeof $input.first().json === 'string') {
  csvText = $input.first().json;
} else {
  csvText = JSON.stringify($input.first().json);
}

// Fallback de segurança se o download falhar ou vier vazio
if (!csvText || !csvText.includes('perfil')) {
  csvText = `perfil,produto,minimo,rentabilidade
Conservador,Poupança,100,6.2%
Conservador,CDB Liquidez Diária,1000,12.5%
Conservador,Tesouro Selic,500,13.0%
Moderado,CDB Prefixado,1000,14.0%
Moderado,Fundo Multimercado,5000,16.0%
Moderado,Tesouro IPCA+,1000,IPCA+6.0%
Arrojado,Ações ETF,500,Variável
Arrojado,Fundo de Ações,10000,Variável
Arrojado,Criptomoedas,100,Variável`;
}

// 2. Parser do CSV de Opções de Investimento
const linhasCsv = csvText.trim().split(/\r?\n/);
const catalogo = [];
for (let i = 1; i < linhasCsv.length; i++) {
  const cols = linhasCsv[i].split(',').map(c => c.trim());
  if (cols.length >= 4) {
    catalogo.push({
      perfil: cols[0],
      produto: cols[1],
      minimo: parseFloat(cols[2]) || 0,
      rentabilidade: cols[3]
    });
  }
}

// 3. Obter a lista de clientes enviada ao Webhook
const webhookData = $('Webhook - Receber Clientes').first().json;
const webhookBody = webhookData.body || webhookData;
const clientes = Array.isArray(webhookBody) ? webhookBody : (webhookBody.clientes || [webhookBody]);

// Função auxiliar para converter saldo formatado (ex: 'R$ 12.500,00') em número
function converterSaldo(valor) {
  if (typeof valor === 'number') return valor;
  const limpo = String(valor || '0')
    .replace(/[^0-9,-]/g, '')
    .replace(',', '.');
  return parseFloat(limpo) || 0;
}

const resultados = [];

// 4. Cruzar cada cliente com as opções de investimento e gerar mensagem estática
for (const cliente of clientes) {
  if (!cliente || !cliente.nome) continue;

  const perfil = (cliente.perfil || 'Conservador').trim();
  const saldoNumerico = converterSaldo(cliente.saldo);

  // Filtrar opções pelo perfil do cliente
  const produtosPerfil = catalogo.filter(p => p.perfil.toLowerCase() === perfil.toLowerCase());

  // Filtrar opções que cabem no saldo do cliente
  const produtosCompativeis = produtosPerfil.filter(p => saldoNumerico >= p.minimo);

  // Definir recomendação principal
  const produtoPrincipal = produtosCompativeis.length > 0
    ? produtosCompativeis[produtosCompativeis.length - 1]
    : (produtosPerfil[0] || { produto: 'Tesouro Selic', rentabilidade: '13.0%', minimo: 500 });

  const outrosProdutos = produtosCompativeis
    .filter(p => p.produto !== produtoPrincipal.produto)
    .map(p => p.produto);

  // 5. Gerar templates de mensagens conforme o perfil (Etapa 4 do Desafio)
  let mensagem = '';
  if (perfil.toLowerCase() === 'conservador') {
    mensagem = `Olá, ${cliente.nome}! 🛡️ Identificamos que seu perfil é Conservador e seu saldo disponível é de ${cliente.saldo}. Para focar em segurança, liquidez e proteção de capital em renda fixa, recomendamos aplicar em ${produtoPrincipal.produto} com rentabilidade de ${produtoPrincipal.rentabilidade} (mínimo de R$ ${produtoPrincipal.minimo}). ${outrosProdutos.length > 0 ? 'Outras opções seguras acessíveis para você: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else if (perfil.toLowerCase() === 'moderado') {
    mensagem = `Olá, ${cliente.nome}! ⚖️ Seu perfil é Moderado com saldo disponível de ${cliente.saldo}. Para construir um mix equilibrado entre segurança de renda fixa e potencial de valorização, indicamos o ${produtoPrincipal.produto} (rentabilidade estimada em ${produtoPrincipal.rentabilidade}). ${outrosProdutos.length > 0 ? 'Outras alternativas para diversificar: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else if (perfil.toLowerCase() === 'arrojado') {
    mensagem = `Olá, ${cliente.nome}! 🚀 Como investidor Arrojado com saldo disponível de ${cliente.saldo}, você tem foco em maior potencial de retorno e tolerância a risco. Sugerimos alocação em ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}, mínimo R$ ${produtoPrincipal.minimo}). ${outrosProdutos.length > 0 ? 'Você também pode diversificar com: ' + outrosProdutos.join(', ') + '.' : ''}`;
  } else {
    mensagem = `Olá, ${cliente.nome}! Seu saldo é ${cliente.saldo}. Recomendamos ${produtoPrincipal.produto} (${produtoPrincipal.rentabilidade}).`;
  }

  resultados.push({
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      saldo_numerico: saldoNumerico,
      perfil: perfil,
      recomendacao_principal: {
        produto: produtoPrincipal.produto,
        rentabilidade: produtoPrincipal.rentabilidade,
        minimo: produtoPrincipal.minimo
      },
      outras_opcoes_compativeis: outrosProdutos,
      mensagem_personalizada: mensagem,
      tipo_mensagem: "Template Estático (MVP)",
      data_processamento: new Date().toISOString()
    }
  });
}

return resultados;

